Called when attribute is not found Get attribute value

```python
class DynamicAttrs:
    def __init__(self):
        self._data = {}

    def __getattr__(self, name):
        """Called when attribute is not found"""
        print(f"Getting attribute: {name}")
        return self._data.get(name, None)

    def __setattr__(self, name, value):
        """Called for all attribute assignments"""
        print(f"Setting attribute: {name} = {value}")
        if name == "_data":
            super().__setattr__(name, value)
        else:
            self._data[name] = value

    def __delattr__(self, name):
        """Called when deleting attribute"""
        print(f"Deleting attribute: {name}")
        if name in self._data:
            del self._data[name]

obj = DynamicAttrs()
obj.name = "Alice"
obj.age = 30
print(f"obj.name = {obj.name}")
print(f"obj.age = {obj.age}")
print(f"obj.unknown = {obj.unknown}")
del obj.age
print()

